def compute(vars):
    prior = vars["v1"]
    current = vars["v2"]
    if prior == 0:
        return None

    change_ratio = (current - prior) / abs(prior)
    return {
        "value": change_ratio,
        "trace": {
            "prior_net_loss": prior,
            "current_net_loss": current,
            "change": current - prior,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
